/**
 * Python → TypeScript: the vectors tau-net wrote (net/vectors.json, generated by
 * packages/tau-net/scripts/make_ts_vectors.py). TypeScript must derive the same keys, agree on
 * encoding and addresses, verify and open every envelope, rebuild each one byte for byte from
 * its inputs, refuse the tampered ones, and sign the same universe requests.
 */

import { describe, expect, it } from "vitest";

import {
  addressParts,
  b64uDecode,
  b64uEncode,
  baseUrl,
  BadSignature,
  BoxError,
  buildEnvelope,
  encodeRequest,
  Identity,
  isAddress,
  makeRequestPayload,
  openEnvelope,
  openVerified,
  parseAddress,
  parseRequest,
  parseTarget,
  signPayload,
  signRequest,
  utf8Decode,
  verifyRequest,
  verifySignature,
  type Kind,
  type UniverseKind,
  type WireEnvelope,
} from "../index.ts";
import vectors from "../vectors.json";

const hex = (bytes: Uint8Array) =>
  Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
const fromHex = (text: string) =>
  new Uint8Array((text.match(/../g) ?? []).map((h) => parseInt(h, 16)));

type Label = keyof typeof vectors.identities;

async function identity(label: string): Promise<Identity> {
  return Identity.fromJson(vectors.identities[label as Label].identity);
}

describe("identities", () => {
  for (const [label, entry] of Object.entries(vectors.identities)) {
    it(`derives ${label}'s public keys and stored forms`, async () => {
      const id = await Identity.fromJson(entry.identity);
      expect(id.signKey).toBe(entry.sign_key);
      expect(id.boxKey).toBe(entry.box_key);
      expect(id.toIdentityJson()).toEqual(entry.identity);
      expect(id.toEnvValue()).toBe(entry.env_value);
      const fromEnv = await Identity.fromEnvValue(entry.env_value);
      expect(fromEnv.signKey).toBe(entry.sign_key);
      expect(fromEnv.boxKey).toBe(entry.box_key);
    });
  }
});

describe("the reference vector of tau-network.md §3", () => {
  const ref = vectors.reference;

  it("has the documented keys, payload and signature", async () => {
    const seeds = { v: 1, sign_seed: ref.sign_seed, box_seed: ref.box_seed };
    const id = await Identity.fromJson(seeds);
    expect(id.signKey).toBe(ref.sign_key);
    expect(id.boxKey).toBe(ref.box_key);
    const payload = b64uDecode(ref.payload)!;
    expect(utf8Decode(payload)).toBe(ref.payload_json);
    const sig = b64uDecode(ref.sig)!;
    expect(await verifySignature(ref.sign_key, payload, sig)).toBe(true);
    expect(b64uEncode(await signPayload(id, payload))).toBe(ref.sig);
  });
});

describe("base64url", () => {
  it.each(vectors.b64u.encode)("encodes $hex", ({ hex: h, b64u }) => {
    expect(b64uEncode(fromHex(h))).toBe(b64u);
  });

  it.each(vectors.b64u.decode)("decodes $text as tau-net does", ({ text, hex: h }) => {
    const decoded = b64uDecode(text);
    expect(decoded === null ? null : hex(decoded)).toBe(h);
  });
});

describe("addresses (plain hosts, tau-net's verdicts)", () => {
  it.each(vectors.addresses.valid)("$address valid: $valid", ({ address, valid }) => {
    expect(isAddress(address)).toBe(valid);
    expect(addressParts(address) !== null).toBe(valid);
  });

  it.each(vectors.addresses.parse_address)("parses $text", ({ text, address }) => {
    expect(parseAddress(text)).toBe(address);
  });

  it.each(vectors.addresses.parse_target)("parses the target $text", ({ text, target }) => {
    expect(parseTarget(text)).toEqual(target);
  });

  it.each(vectors.addresses.base_url)(
    "$address (insecure allowed: $allow_insecure) is at $url",
    ({ address, allow_insecure, url }) => {
      expect(baseUrl(address, allow_insecure)).toBe(url);
    },
  );
});

describe("envelopes", () => {
  for (const vector of vectors.envelopes) {
    const input = vector.input;

    it(`${vector.name}: verifies and opens`, async () => {
      const sender = vectors.identities[vector.sender as Label];
      const recipient = await identity(vector.recipient);
      const opened = await openEnvelope(vector.envelope, sender.sign_key, recipient);
      expect(opened.payload).toEqual(vector.payload);
      expect(opened.raw).toEqual(input.content);
    });

    it(`${vector.name}: rebuilds byte for byte`, async () => {
      const sender = await identity(vector.sender);
      const recipient = vectors.identities[vector.recipient as Label];
      const built = await buildEnvelope(sender, {
        from: input.from,
        to: input.to,
        recipientBoxKey: recipient.box_key,
        kind: input.kind as Kind,
        content: input.content,
        id: input.id,
        thread: input.thread,
        replyTo: input.reply_to,
        hops: input.hops,
        ts: input.ts,
        seal: {
          ephemeralSecret: b64uDecode(input.ephemeral_secret)!,
          nonce: b64uDecode(input.nonce)!,
        },
      });
      expect(built.envelope).toEqual(vector.envelope);
      expect(built.payload).toEqual(vector.payload);
    });
  }

  it("reads sub and ignores unknown keys like tau-net", async () => {
    const find = (name: string) => vectors.envelopes.find((v) => v.name === name)!;
    const open = async (name: string) => {
      const v = find(name);
      return openEnvelope(
        v.envelope,
        vectors.identities[v.sender as Label].sign_key,
        await identity(v.recipient),
      );
    };
    expect((await open("message_for_sub")).content).toEqual({
      text: "Can your coach look at my 10k plan?",
      sub: "coach",
    });
    expect((await open("message_unknown_keys")).content).toEqual({ text: "Hello" });
    expect((await open("visit")).content).toEqual({
      text: "Hi! Can you help me plan a 10k?",
      sub: "coach",
    });
  });
});

describe("tampered envelopes", () => {
  for (const vector of vectors.bad_envelopes) {
    it(`${vector.name} is refused (${vector.expect})`, async () => {
      const envelope: WireEnvelope = vector.envelope;
      if (vector.expect === "bad_signature") {
        await expect(openVerified(envelope, vector.sign_key)).rejects.toBeInstanceOf(BadSignature);
        return;
      }
      const opener = await identity(vector.open_with!);
      await expect(openEnvelope(envelope, vector.sign_key, opener)).rejects.toBeInstanceOf(
        BoxError,
      );
    });
  }
});

describe("universe requests", () => {
  for (const vector of vectors.universe) {
    it(`${vector.name}: verifies and parses`, async () => {
      const signer = vectors.identities[vector.signer as Label];
      const parsed = parseRequest(encodeRequest(vector.request));
      expect(await verifyRequest(signer.sign_key, parsed.payloadBytes, parsed.sig)).toBe(true);
      expect(parsed.payload).toEqual(vector.payload);
    });

    it(`${vector.name}: signs the same bytes from the same fields`, async () => {
      const { kind, ...fields } = vector.input;
      const payload = makeRequestPayload(kind as UniverseKind, fields);
      expect(payload).toEqual(vector.payload);
      const request = await signRequest(await identity(vector.signer), payload);
      expect(request).toEqual(vector.request);
    });
  }

  it("keeps envelope and universe signatures apart", async () => {
    const d = vectors.domain_separation;
    const payload = b64uDecode(d.payload)!;
    const envelopeSig = b64uDecode(d.envelope_sig)!;
    const universeSig = b64uDecode(d.universe_sig)!;
    expect(await verifySignature(d.sign_key, payload, envelopeSig)).toBe(true);
    expect(await verifyRequest(d.sign_key, payload, universeSig)).toBe(true);
    expect(await verifySignature(d.sign_key, payload, universeSig)).toBe(false);
    expect(await verifyRequest(d.sign_key, payload, envelopeSig)).toBe(false);
  });
});
